reveal <- function(word, guessed) {
  chars <- strsplit(word, "")[[1]]
  paste(ifelse(chars %in% guessed, chars, "_"), collapse = " ")
}

is_won <- function(word, guessed) {
  chars <- strsplit(word, "")[[1]]
  all(chars %in% guessed)
}
